const upsertCampaignImportPart = `-- name: UpsertCampaignImportPart :exec
INSERT INTO campaign_import_parts (import_id, part_number, byte_size, created_at)
VALUES ($1, $2, $3, $4)
ON CONFLICT (import_id, part_number) DO UPDATE SET byte_size = excluded.byte_size, created_at = excluded.created_at
`

type UpsertCampaignImportPartParams struct {
	ImportID   string
	PartNumber int32
	ByteSize   int32
	CreatedAt  time.Time
}

func (q *Queries) UpsertCampaignImportPart(ctx context.Context, arg UpsertCampaignImportPartParams) error {
	_, err := q.db.Exec(ctx, upsertCampaignImportPart,
		arg.ImportID,
		arg.PartNumber,
		arg.ByteSize,
		arg.CreatedAt,
	)
	return err
}
